# build_ofn_v0_10_draft2.py — OFN v0.10 Draft 2 (release candidate) from Draft 1 (OFN co-owner SESSION, 19 Oct 2026)
# Chain: v0.9 (5ae8fdab…9795) --build_ofn_v0_10_draft1.py--> Draft 1 (d94e1e39…8c36) --this script--> Draft 2.
# Applies the two nonblocking editorial corrections of the second co-owner review (C2-A, C2-B) plus status metadata.
import hashlib, sys, re
D1 = sys.argv[1] if len(sys.argv) > 1 else 'RTG_ONTOLOGICAL_FOUNDATIONS_v0_10_DRAFT1.md'
OUT = sys.argv[2] if len(sys.argv) > 2 else 'RTG_ONTOLOGICAL_FOUNDATIONS_v0_10_DRAFT2.md'
D1_SHA = 'd94e1e39f90fd66a485be0e40b614bf36a16a07324aa4e29397ed4be04db8c36'
raw = open(D1, 'rb').read()
assert hashlib.sha256(raw).hexdigest() == D1_SHA, 'input is not Draft 1'
s = raw.decode('utf-8'); d1 = s; log = []
def rep(old, new, tag):
    global s
    assert s.count(old) == 1, (tag, s.count(old)); s = s.replace(old, new); log.append(tag)
# C2-A: import count
rep('Nine new administrative imports and five reference records are added (§11.4–§11.5).',
    'Five new claim-level imports (IMP-O10-01–05) and five reference-only records (RF-O10-01–05) are added (§11.4–§11.5).', 'C2-A import count')
# C2-B: visible evidence grade in §5.5.7
rep('The fifth-order ψ-modulus (RF-O10-02) establishes a nontrivial formal conjugacy obstruction within the stated class.',
    'The fifth-order ψ-modulus `[ALG — SESSION; RF-O10-02]` establishes a nontrivial formal conjugacy obstruction within its stated scope. The universal finite-$a$ classification retains the FMS symbolic P4 evidence qualification (`[ALG — SESSION; FMS symbolic P4 reported, OFN sampled verification]`). These mathematical grades are independent of the interpretive tag on this paragraph.', 'C2-B §5.5.7 grade')
# status metadata
rep('# RTG_ONTOLOGICAL_FOUNDATIONS_v0.10 — DRAFT 1 (adoption pending)', '# RTG_ONTOLOGICAL_FOUNDATIONS_v0.10 — DRAFT 2 / release candidate (adoption pending)', 'M1 title')
rep('**Document status:** **DRAFT 1 — ADOPTION PENDING.**', '**Document status:** **DRAFT 2 — RELEASE CANDIDATE, ADOPTION PENDING.**', 'M2 status')
rep('**Revision editor:** Claude (OFN co-owner), Draft 1. Second OFN co-owner (ChatGPT) review of this draft is pending.',
    '**Revision editor:** Claude (OFN co-owner). Draft 1 (SHA-256 `d94e1e39…8c36`, preserved unchanged with its build record) was reviewed by the second OFN co-owner (ChatGPT) on 19 October 2026: deterministic rebuild reproduced, O10-P1–P7 accepted at their stated scopes, two nonblocking editorial corrections requested. Draft 2 applies exactly those two corrections (C2-A, C2-B) and this status metadata; no scientific content changed. **PI adoption, if given, refers to this Draft 2 file and its hash.**', 'M3 editor')
rep('*v0.10 Draft 1:* no adoption is recorded. Proposals O10-P1–P7 (§12.5) await the second co-owner\'s draft review and a separate PI decision.',
    '*v0.10 Draft 1 / Draft 2:* no adoption is recorded. The second co-owner accepted Draft 1 with two editorial corrections, applied in Draft 2; proposals O10-P1–P7 (§12.5) await a separate PI decision on Draft 2.', 'M4 §0.3')
rep('**Review needed before adoption:** second co-owner review of this draft against v0.8.2; PI decisions on O10-P1–P7, individually or together.',
    '**Review status (Draft 2):** second co-owner review of Draft 1 completed on 19 October 2026 (REVIEW ACCEPTED, two nonblocking editorial corrections; O10-P7 notices to be issued only after adoption). Draft 2 = Draft 1 + C2-A (import count in the status summary) + C2-B (visible `[ALG — SESSION]` grade in §5.5.7) + status metadata, generated by `build_ofn_v0_10_draft2.py`. Remaining: PI decisions on O10-P1–P7, individually or together, on the Draft 2 hash.', 'M5 §12.5')
rep('### v0.10 — 19 October 2026 — Draft 1 / adoption pending (not adopted)',
    '''### v0.10 — 19 October 2026 — Draft 2 / release candidate, adoption pending (not adopted)

- **Input:** Draft 1 (SHA-256 `d94e1e39…8c36`), preserved unchanged with `build_ofn_v0_10_draft1.py` (`6a4fe7af…58ff`).
- **Review:** second OFN co-owner, 19 October 2026: rebuild reproduced; scientific scope, the two local results, imports, FMS dispositions and OPEN layout accepted; O10-P1–P7 fit for PI decision; O10-P7 to be applied only after adoption.
- **Changes:** C2-A status-summary count corrected to five imports and five reference records; C2-B §5.5.7 cites `[ALG — SESSION; RF-O10-02]` and the FMS P4 qualification. Status metadata only otherwise. No new claim, RID or status.

### v0.10 — 19 October 2026 — Draft 1 / adoption pending (not adopted)''', 'M6 Appendix C')
rep('*END OF DOCUMENT — RTG_ONTOLOGICAL_FOUNDATIONS_v0.10 — DRAFT 1*', '*END OF DOCUMENT — RTG_ONTOLOGICAL_FOUNDATIONS_v0.10 — DRAFT 2 / release candidate*', 'M7 footer')
open(OUT, 'w', encoding='utf-8', newline='\n').write(s)
rid = lambda t: set(re.findall(r'RTG-OFN-[A-Z0-9-]+', t))
st = lambda t: re.findall(r'^Status: .*$', t, re.M)
ok = rid(d1) == rid(s) and st(d1) == st(s) and set(re.findall(r'<a id="([^"]+)"', d1)) == set(re.findall(r'<a id="([^"]+)"', s))
changed = sum(1 for a, b in zip(d1.split('\n'), s.split('\n')) if a != b)
print('edits:', len(log), log)
print('RIDs, anchors and Status lines identical to Draft 1:', ok)
print('Draft 2 sha256:', hashlib.sha256(s.encode()).hexdigest(), 'lines', s.count('\n'))
sys.exit(0 if ok else 1)
